const form=document.querySelector('#budget-form'),type=document.querySelector('#type');function selectType(value){type.value=value;document.querySelectorAll('.occasion').forEach(b=>{const on=b.dataset.type===value;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on))})}document.querySelectorAll('[data-type]').forEach(b=>b.addEventListener('click',()=>selectType(b.dataset.type)));type.addEventListener('change',()=>selectType(type.value));const date=form.elements.date;const now=new Date();date.min=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const text=`Olá, equipe La Bella Luna! Gostaria de solicitar um orçamento.\n\nNome: ${form.elements.name.value.trim()}\nData do evento: ${date.value.split('-').reverse().join('/')}\nTipo de evento: ${type.value}\nNúmero de convidados: ${form.elements.guests.value}\n\nGostaria de saber a disponibilidade e receber uma proposta. Obrigado!`;const url='https://wa.me/5571991409542?text='+encodeURIComponent(text);document.querySelector('#send-again').href=url;form.hidden=true;document.querySelector('#ready').hidden=false;window.open(url,'_blank','noopener,noreferrer')});document.querySelector('#edit').addEventListener('click',()=>{form.hidden=false;document.querySelector('#ready').hidden=true;form.elements.name.focus()});const scenes={jardim:{label:'O espaço · La Bella Luna',title:'O cenário do<br>seu grande dia.',text:'Jardins, capela e salões para receber a sua celebração em Lauro de Freitas. Venha conhecer os ambientes em uma visita.',alt:'Pergolado florido e jardim do La Bella Luna'},brinde:{label:'A celebração · La Bella Luna',title:'Um brinde às<br>boas histórias.',text:'Um encontro com as pessoas que fazem parte da sua vida. Conte à equipe como você imagina viver esse dia.',alt:'Noivos brindam com espumante no jardim do La Bella Luna'},flor:{label:'Os detalhes · La Bella Luna',title:'A beleza está<br>em cada escolha.',text:'As flores, a luz e os detalhes que deixam o evento com a sua personalidade. Converse com a equipe sobre a sua celebração.',alt:'Orquídea branca na lapela do noivo'}};document.querySelectorAll('[data-scene]').forEach(b=>b.addEventListener('click',()=>{const scene=scenes[b.dataset.scene];document.querySelector('#scene-photo').src='assets/'+b.dataset.scene+'.webp';document.querySelector('#scene-photo').alt=scene.alt;document.querySelector('#scene-title').innerHTML=scene.title;document.querySelector('#scene-label').textContent=scene.label;document.querySelector('#scene-text').textContent=scene.text;document.querySelectorAll('[data-scene]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))})}));const strip=document.querySelector('#gallery-strip'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;function moveGallery(direction){strip.scrollBy({left:direction*(strip.clientWidth*.7),behavior:reduced?'instant':'smooth'})}document.querySelector('#gallery-prev').addEventListener('click',()=>moveGallery(-1));document.querySelector('#gallery-next').addEventListener('click',()=>moveGallery(1));strip.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();moveGallery(e.key==='ArrowRight'?1:-1)}});const lightbox=document.querySelector('#lightbox');document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>{const img=document.querySelector('#lightbox-image');img.src='assets/'+b.dataset.photo+'.webp';img.alt=b.querySelector('img').alt;lightbox.showModal()}));document.querySelector('#close-photo').addEventListener('click',()=>lightbox.close());lightbox.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close()});const menu=document.querySelector('#mobile-menu'),menuButton=document.querySelector('#menu-button');function closeMenu(){menu.hidden=true;menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Abrir menu')}menuButton.addEventListener('click',()=>{menu.hidden=!menu.hidden;menuButton.setAttribute('aria-expanded',String(!menu.hidden));menuButton.setAttribute('aria-label',menu.hidden?'Abrir menu':'Fechar menu')});menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));if(!reduced){let queued=false;window.addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(()=>{const progress=Math.min(1,scrollY/innerHeight);document.querySelector('#hero-photo').style.transform=`scale(${1+progress*.08})`;queued=false})}},{passive:true});}if('IntersectionObserver' in window){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('motion-in');io.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.intro h2,.intro-text p,.intro-links,.gallery-heading h2,.gallery-heading p,.gallery-strip,.enquiry-heading h2,.enquiry-heading>p,.form-shell,.footer-main>div').forEach((el,i)=>{el.style.animationDelay=(i%3)*65+'ms';io.observe(el)})}
